/*
 * CLIMATE CHANGE 02 — POLAR ICE / MELTING BOUNDARY
 * 25 seconds | 3 scenes | seamless loop | 3840 x 2160 | 60 fps
 * Render interface: draw(ctx, timeInSeconds, width, height).
 * Pure, deterministic Canvas 2D. No external assets, DOM or libraries.
 * Static background. No glow, bloom, light aura, shadows or blur.
 * VIDEO ENCODER TARGET: 100,000,000 bits/second (100 Mbps).
 * Bitrate must be enforced by the exporter, not by this drawing function.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const unit = minSide / 900;
  const phase = TAU * loopT / duration;
  const C = {
    ink: '#345569', iceA: '#FAF9ED', iceB: '#D5E9E8',
    iceLine: '#91BAC5', seaA: '#9FCBD2', seaB: '#67A8BE',
    deep: '#508DA8', cream: '#F3F0E3', amber: '#DDA579'
  };
  function clamp(x) { return Math.max(0, Math.min(1, x)); }
  function mix(a, b, p) { return a + (b - a) * p; }
  function mod(x) { return ((x % 1) + 1) % 1; }
  function smooth(a, b, x) {
    const p = clamp((x - a) / (b - a));
    return p * p * (3 - 2 * p);
  }
  function ease(x) {
    x = clamp(x);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }
  function stroke(color, lineWidth) {
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
  }
  function circle(x, y, r, fill, outline, lineWidth) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (outline) stroke(outline, lineWidth || 3.5);
  }
  function rounded(x, y, w, h, r) {
    r = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function polygon(points, fill, outline, lineWidth) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (outline) stroke(outline, lineWidth || 3.8);
  }

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  // This background is identical on every frame of every scene.
  const bg = ctx.createLinearGradient(0, 0, width, height);
  bg.addColorStop(0, '#E3ECE6');
  bg.addColorStop(0.53, '#C6DCE2');
  bg.addColorStop(1, '#C1CCDE');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2 + minSide * 0.026);
  ctx.scale(unit, unit);

  function wave(x, level) {
    return level
      + 3.5 * Math.sin((x + 440) / 79 - phase * 8)
      + 1.5 * Math.sin((x + 440) / 43 + phase * 5);
  }
  function waveSlope(x) {
    return (3.5 / 79) * Math.cos((x + 440) / 79 - phase * 8)
      + (1.5 / 43) * Math.cos((x + 440) / 43 + phase * 5);
  }
  function oceanPath(level) {
    ctx.beginPath();
    ctx.moveTo(-440, wave(-440, level));
    for (let x = -430; x <= 310; x += 10) ctx.lineTo(x, wave(x, level));
    ctx.lineTo(310, 204);
    ctx.quadraticCurveTo(310, 261, 253, 261);
    ctx.lineTo(-383, 261);
    ctx.quadraticCurveTo(-440, 261, -440, 204);
    ctx.closePath();
  }
  function icePoints(melt) {
    const full = [
      [-330,22],[-320,-65],[-273,-90],[-245,-172],[-176,-214],[-135,-292],
      [-61,-249],[-18,-178],[35,-126],[81,-100],[113,-83],[90,-69],
      [82,-38],[100,14],[46,102],[-53,145],[-179,126],[-282,86]
    ];
    const reduced = [
      [-310,30],[-298,-46],[-254,-71],[-223,-150],[-161,-184],[-128,-251],
      [-72,-214],[-31,-153],[19,-108],[65,-88],[97,-73],[77,-62],
      [69,-24],[77,24],[29,99],[-62,126],[-169,114],[-267,81]
    ];
    return full.map((point, i) => [mix(point[0], reduced[i][0], melt), mix(point[1], reduced[i][1], melt)]);
  }
  function drawIce(melt, mode, p) {
    const points = icePoints(melt);
    const fill = ctx.createLinearGradient(-210, -285, -70, 154);
    fill.addColorStop(0, C.iceA);
    fill.addColorStop(1, C.iceB);
    polygon(points, fill);
    ctx.save();
    polygon(points);
    ctx.clip();

    // Flat contour bands, not faceted shading or 3D surfaces.
    for (let i = 0; i < 4; i++) {
      const y = -168 + i * 74 + melt * 13;
      ctx.beginPath();
      ctx.moveTo(-355, y + 16);
      ctx.bezierCurveTo(-255, y - 1, -130, y + 19, 54, y + 3);
      stroke(C.iceLine, 2.6);
    }
    const crack = mode === 0 ? 0.30 * smooth(0.14, 0.76, p)
      : mode === 1 ? mix(0.30, 1, smooth(0.04, 0.52, p)) : 1;
    const route = [[-109,-211],[-125,-179],[-103,-151],[-116,-119],[-91,-91]];
    const length = crack * (route.length - 1);
    ctx.beginPath();
    ctx.moveTo(route[0][0] - melt * 7, route[0][1] + melt * 22);
    for (let i = 1; i < route.length; i++) {
      if (length >= i) ctx.lineTo(route[i][0] - melt * 7, route[i][1] + melt * 22);
      else if (length > i - 1) {
        const q = length - (i - 1);
        ctx.lineTo(mix(route[i - 1][0], route[i][0], q) - melt * 7,
          mix(route[i - 1][1], route[i][1], q) + melt * 22);
        break;
      }
    }
    stroke(C.ink, 2.4);
    if (mode > 0) {
      ctx.save();
      ctx.globalAlpha *= smooth(0.07, 0.32, p + (mode === 2 ? 1 : 0));
      ctx.beginPath();
      ctx.moveTo(32 - melt * 10, -92 + melt * 10);
      ctx.lineTo(22 - melt * 10, -62 + melt * 10);
      ctx.lineTo(39 - melt * 10, -45 + melt * 10);
      stroke(C.ink, 2.5);
      ctx.restore();
    }
    ctx.restore();
    polygon(points, null, C.ink, 4.5);
  }

  function drawFragment(x, level, size, opacity) {
    if (opacity <= 0) return;
    const y = wave(x, level) - 7 * size;
    // Buoyancy and angle are derived from the same surface, without independent wobble.
    const angle = Math.atan(waveSlope(x)) * 0.72;
    ctx.save();
    ctx.globalAlpha *= opacity;
    ctx.translate(x, y);
    ctx.rotate(angle);
    ctx.scale(size, size);
    polygon([[-24,-11],[-11,-27],[15,-24],[27,-6],[19,15],[-18,14]], C.iceA, C.ink, 3.7);
    ctx.beginPath();
    ctx.moveTo(-10, -8);
    ctx.lineTo(8, -11);
    stroke(C.iceLine, 2.3);
    ctx.restore();
  }

  function drawCurrents(level, mode) {
    ctx.save();
    oceanPath(level);
    ctx.clip();
    const xLanes = [-407, -355, 195, 266];
    for (let i = 0; i < xLanes.length; i++) {
      const q = mod(loopT * 7 / duration + i * 0.237);
      const x = xLanes[i] + 3 * Math.sin(phase * 3 + i);
      const y = mix(234, level + 57, q);
      ctx.save();
      ctx.globalAlpha *= 0.34 * Math.pow(Math.sin(Math.PI * q), 2);
      circle(x, y, 2.8 + (i % 2), C.cream);
      ctx.restore();
    }
    for (let row = 0; row < 2; row++) {
      for (let j = 0; j < 3; j++) {
        const q = mod(loopT * 2 / duration + j / 3 + row * 0.13);
        const x = mix(-434, 310, q);
        const y = 164 + row * 54 + 2 * Math.sin(phase * 4 + j);
        ctx.save();
        ctx.globalAlpha *= 0.28 * Math.pow(Math.sin(Math.PI * q), 2);
        ctx.beginPath();
        ctx.moveTo(x - 20, y);
        ctx.quadraticCurveTo(x, y + 3, x + 20, y);
        stroke(C.cream, 2.6);
        ctx.restore();
      }
    }
    ctx.restore();
  }

  function drawMeltDrop(melt, level, mode, p) {
    const corridorClear = mode === 1
      ? clamp(1 - smooth(0.18, 0.23, p) + smooth(0.54, 0.62, p)) : 1;
    const strength = (mode === 0 ? 0.36 * smooth(0.26, 0.60, p) : 1) * corridorClear;
    if (strength <= 0) return;
    const sourceX = mix(113, 97, melt) + 5;
    const sourceY = mix(-83, -73, melt) + 4;
    const impactX = sourceX + 10;
    const impactY = wave(impactX, level);
    const space = impactY - sourceY;
    if (space < 11) return;
    const q = mod(loopT * 16 / duration);
    const dropAlpha = strength * Math.min(1, space / 31);
    ctx.save();
    ctx.globalAlpha *= dropAlpha;
    if (q < 0.20) {
      const grow = smooth(0, 0.20, q);
      // A single coherent pendant drop, attached only during its formation.
      ctx.beginPath();
      ctx.moveTo(sourceX, sourceY - 1);
      ctx.bezierCurveTo(sourceX - 3.7 * grow, sourceY + 3,
        sourceX - 5 * grow, sourceY + 8 * grow, sourceX, sourceY + 10 * grow);
      ctx.bezierCurveTo(sourceX + 5 * grow, sourceY + 8 * grow,
        sourceX + 3.7 * grow, sourceY + 3, sourceX, sourceY - 1);
      ctx.closePath();
      ctx.fillStyle = C.seaB;
      ctx.fill();
    } else if (q < 0.62) {
      const fall = (q - 0.20) / 0.42;
      const x = mix(sourceX, impactX, fall);
      const y = mix(sourceY + 6.5, impactY - 3, fall * fall);
      ctx.beginPath();
      ctx.ellipse(x, y, 3.1, 4.2, 0, 0, TAU);
      ctx.fillStyle = C.seaB;
      ctx.fill();
    } else {
      const ripple = (q - 0.62) / 0.38;
      ctx.save();
      ctx.globalAlpha *= 1 - smooth(0, 1, ripple);
      ctx.beginPath();
      ctx.ellipse(impactX, impactY + 1, mix(4, 20, ripple), mix(1.5, 4, ripple), 0, 0, TAU);
      stroke(C.cream, 2.1);
      ctx.restore();
    }
    ctx.restore();
  }

  function drawGauge(level, mode, p) {
    const x = 397;
    rounded(x - 30, -183, 60, 435, 28);
    ctx.fillStyle = C.cream;
    ctx.fill();
    stroke(C.ink, 4.5);
    ctx.save();
    rounded(x - 17, -166, 34, 403, 16);
    ctx.clip();
    ctx.fillStyle = '#D6E1DD';
    ctx.fillRect(x - 20, -169, 40, 410);
    const fill = ctx.createLinearGradient(0, -120, 0, 237);
    fill.addColorStop(0, C.seaA);
    fill.addColorStop(1, C.deep);
    ctx.beginPath();
    ctx.moveTo(x - 21, 240);
    ctx.lineTo(x - 21, level);
    for (let j = -21; j <= 21; j += 3)
      ctx.lineTo(x + j, level + 1.5 * Math.sin(j / 9 + phase * 8));
    ctx.lineTo(x + 21, 240);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.restore();
    rounded(x - 17, -166, 34, 403, 16);
    stroke(C.iceLine, 1.9);
    for (let i = 0; i < 9; i++) {
      const y = -139 + i * 39;
      ctx.beginPath();
      ctx.moveTo(x - (i % 2 === 0 ? 60 : 53), y);
      ctx.lineTo(x - 43, y);
      stroke(C.ink, i % 2 === 0 ? 2.8 : 2.1);
    }
    // Pointer is outside the housing; it never intersects the tick lane.
    polygon([[x + 45, level], [x + 59, level - 9], [x + 59, level + 9]],
      mode === 2 ? C.amber : C.iceA, C.ink, 2.9);

    rounded(x - 20, 269, 40, 17, 7);
    ctx.fillStyle = C.ink;
    ctx.fill();
    for (let i = 0; i < 3; i++) {
      const active = 0.45 + 0.55 * Math.pow(0.5 + 0.5 * Math.sin(phase * 6 - i), 2);
      ctx.save();
      ctx.globalAlpha *= active;
      circle(x - 11 + i * 11, 277.5, 2.6, mode === 2 ? C.amber : C.iceA);
      ctx.restore();
    }
    if (mode === 2) {
      const extend = smooth(0.06, 0.34, p);
      ctx.save();
      ctx.globalAlpha *= extend;
      const y = -221;
      rounded(x - 25, y, 50, 24, 7);
      ctx.fillStyle = C.amber;
      ctx.fill();
      stroke(C.ink, 2.8);
      ctx.beginPath();
      ctx.moveTo(x - 9, y + 15);
      ctx.lineTo(x, y + 8);
      ctx.lineTo(x + 9, y + 15);
      stroke(C.ink, 2.8);
      ctx.restore();
    }
  }

  function renderScene(mode, p, offset, alpha) {
    if (alpha <= 0) return;
    ctx.save();
    ctx.translate(offset - 3, 0);
    ctx.globalAlpha *= alpha;
    let melt, level;
    if (mode === 0) {
      melt = mix(0, 0.06, smooth(0.10, 0.80, p));
      level = mix(18, 12, smooth(0.10, 0.80, p));
    } else if (mode === 1) {
      const change = ease((p - 0.035) / 0.77);
      melt = mix(0.06, 0.95, change);
      level = mix(12, -32, change);
    } else {
      melt = mix(0.95, 0.98, smooth(0.04, 0.70, p));
      level = mix(-32, -54, ease(p / 0.76));
    }

    const sea = ctx.createLinearGradient(0, -66, 0, 264);
    sea.addColorStop(0, C.seaA);
    sea.addColorStop(1, C.seaB);
    oceanPath(level);
    ctx.fillStyle = sea;
    ctx.fill();

    drawIce(melt, mode, p);
    const leftX = -387 + 4 * Math.sin(phase * 2);
    drawFragment(leftX, level, 0.91, 1);
    const calve = mode === 1 ? ease((p - 0.24) / 0.56) : mode === 2 ? 1 : 0;
    const rightOpacity = mode === 1 ? smooth(0.24, 0.34, p) : mode === 2 ? 1 : 0;
    drawFragment(mix(142, 238, calve), level, 1.03, rightOpacity);

    // Deliberate front-water occlusion keeps all submerged objects in one water body.
    ctx.save();
    oceanPath(level);
    ctx.clip();
    ctx.globalAlpha *= 0.26;
    ctx.fillStyle = C.deep;
    ctx.fillRect(-444, -76, 758, 342);
    ctx.restore();
    drawCurrents(level, mode);

    ctx.beginPath();
    ctx.moveTo(-440, wave(-440, level));
    for (let x = -430; x <= 310; x += 10) ctx.lineTo(x, wave(x, level));
    stroke('#E5F1E9', 3.0);
    oceanPath(level);
    stroke(C.ink, 4.5);

    drawMeltDrop(melt, level, mode, p);
    drawGauge(level, mode, p);
    ctx.restore();
  }

  // Three actual scene changes. Re-entry restores the original ice behind the slide.
  // Incoming and outgoing compositions have more than 190 units of separation.
  const transition = smooth(0.84, 1, sceneProgress);
  const travel = 1110;
  renderScene(currentScene, sceneProgress, -travel * transition,
    1 - smooth(0.72, 1, transition));
  if (transition > 0) {
    renderScene((currentScene + 1) % sceneCount, 0, travel * (1 - transition),
      smooth(0, 0.22, transition));
  }
  ctx.restore();
}

/*
 * CLIMATE CHANGE 01 — PLANET HEAT MONITOR
 * 25 seconds | 3 scenes | seamless loop | 3840 x 2160 | 60 fps
 * Render interface: draw(ctx, timeInSeconds, width, height).
 * Self-contained, deterministic Canvas 2D. No assets, DOM or dependencies.
 * Static background. No glow, shadows, bloom, noise or blur.
 * VIDEO ENCODER TARGET: 100,000,000 bits/second (100 Mbps).
 * The video exporter must enforce that bitrate; Canvas does not encode video.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const unit = minSide / 900;
  const phase = TAU * loopT / duration;
  const C = {
    ink: '#243D50', oceanA: '#D7ECE9', oceanB: '#A8D2D3',
    landA: '#91B5A2', landB: '#6E9D96', cream: '#F5ECDD',
    coral: '#E58C76', amber: '#EAC086', blue: '#6FAEC2',
    ring: '#B9D0D3', pale: '#DAE9E7'
  };

  function clamp(x) { return Math.max(0, Math.min(1, x)); }
  function smooth(a, b, x) {
    const p = clamp((x - a) / (b - a));
    return p * p * (3 - 2 * p);
  }
  function ease(x) {
    x = clamp(x);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }
  function mix(a, b, p) { return a + (b - a) * p; }
  function mod(x) { return ((x % 1) + 1) % 1; }
  function stroke(color, lineWidth) {
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
  }
  function circle(x, y, r, fill, outline, lineWidth) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (outline) stroke(outline, lineWidth || 4);
  }
  function rounded(x, y, w, h, r) {
    r = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function polygon(points, fill, outline, lineWidth) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (outline) stroke(outline, lineWidth || 3.6);
  }

  // All background coordinates and colors are time-independent.
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  const bg = ctx.createLinearGradient(0, 0, width, height);
  bg.addColorStop(0, '#172C43');
  bg.addColorStop(0.55, '#3D5263');
  bg.addColorStop(1, '#8B6B70');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);

  ctx.translate(width / 2, height / 2 + minSide * 0.025);
  ctx.scale(unit, unit);

  function thermometerPath(cx, inner) {
    const neck = inner ? 15 : 29;
    const r = inner ? 34 : 48;
    const cy = 166;
    const top = inner ? -198 : -216;
    const joinY = cy - Math.sqrt(r * r - neck * neck);
    const a = Math.acos(neck / r);
    ctx.beginPath();
    ctx.moveTo(cx - neck, joinY);
    ctx.lineTo(cx - neck, top + neck);
    ctx.quadraticCurveTo(cx - neck, top, cx, top);
    ctx.quadraticCurveTo(cx + neck, top, cx + neck, top + neck);
    ctx.lineTo(cx + neck, joinY);
    ctx.arc(cx, cy, r, -a, Math.PI + a);
    ctx.closePath();
  }

  function drawThermometer(temperature, intro, mode, p) {
    const cx = 305;
    const level = mix(42, -169, temperature);
    thermometerPath(cx, false);
    ctx.fillStyle = C.cream;
    ctx.fill();
    stroke(C.ink, 5);

    ctx.save();
    thermometerPath(cx, true);
    ctx.clip();
    ctx.fillStyle = '#D4DED9';
    ctx.fillRect(cx - 38, -204, 76, 410);
    const liquid = ctx.createLinearGradient(0, -182, 0, 199);
    liquid.addColorStop(0, C.coral);
    liquid.addColorStop(0.49, C.amber);
    liquid.addColorStop(1, C.blue);
    ctx.beginPath();
    ctx.moveTo(cx - 40, 203);
    ctx.lineTo(cx - 40, level);
    for (let x = cx - 40; x <= cx + 40; x += 4) {
      const y = level + 1.7 * Math.sin((x - cx) * 0.115 + phase * 12);
      ctx.lineTo(x, y);
    }
    ctx.lineTo(cx + 40, 203);
    ctx.closePath();
    ctx.fillStyle = liquid;
    ctx.fill();

    // Bubbles remain inside the liquid chamber and fade before wrapping.
    const liquidAlpha = ctx.globalAlpha;
    for (let i = 0; i < 3; i++) {
      const q = mod(loopT * 8 / duration + i / 3);
      const alpha = Math.pow(Math.sin(Math.PI * q), 2) * 0.30;
      const x = cx + (i - 1) * 10 + 2 * Math.sin(phase * 4 + i);
      const y = mix(188, 132, q);
      ctx.globalAlpha = liquidAlpha * alpha;
      circle(x, y, 2.6 + (i % 2), C.cream);
    }
    ctx.restore();

    thermometerPath(cx, true);
    stroke(C.ink, 2.2);

    ctx.save();
    ctx.globalAlpha *= 0.54 + 0.46 * intro;
    for (let i = 0; i < 9; i++) {
      const y = -178 + i * 34;
      ctx.beginPath();
      ctx.moveTo(cx + 46, y);
      ctx.lineTo(cx + (i % 2 === 0 ? 64 : 56), y);
      stroke(C.pale, 3);
    }
    ctx.restore();

    // Indicator occupies its own corridor, clear of the scale and bulb.
    const mx = cx + 91;
    polygon([[mx - 9, level], [mx + 4, level - 9], [mx + 4, level + 9]],
      mode === 2 ? C.coral : C.amber, C.ink, 2.8);
    rounded(mx + 12, level - 12, 24, 24, 6);
    ctx.fillStyle = C.cream;
    ctx.fill();
    stroke(C.ink, 2.8);
    ctx.beginPath();
    ctx.moveTo(mx + 24, level - 5);
    ctx.lineTo(mx + 24, level + 5);
