      [[-107,18],[-78,29],[-53,54],[-57,81],[-76,103],[-83,135],[-111,171],[-119,148],[-118,105],[-132,77],[-134,46]],
      [[-5,-116],[21,-136],[55,-127],[65,-108],[47,-87],[27,-94],[15,-77],[-8,-83],[-19,-102]],
      [[-12,-66],[25,-76],[55,-53],[64,-22],[43,14],[29,53],[5,71],[-12,41],[-21,10],[-42,-15],[-31,-49]],
      [[77,-142],[119,-145],[159,-111],[183,-61],[170,-26],[137,-35],[121,-7],[91,-25],[86,-58],[61,-72],[77,-95]],
      [[108,86],[145,67],[181,94],[169,123],[138,134],[115,117]],
      [[-89,-179],[-54,-181],[-45,-157],[-61,-143],[-82,-151]]
    ];
    for (let i = 0; i < lands.length; i++) {
      const reveal = mode === 0 ? 0.45 + 0.55 * smooth(0.015 + i * 0.018, 0.20 + i * 0.018, p) : 1;
      ctx.save();
      ctx.globalAlpha *= reveal;
