    ctx.beginPath();
    ctx.moveTo(144, 130);
    ctx.lineTo(198, 130);
    ctx.quadraticCurveTo(210, 130, 210, 142);
    ctx.lineTo(210, 150);
    ctx.quadraticCurveTo(210, 162, 222, 162);
    ctx.lineTo(253, 162);
