  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 3; col++) {
      const x = -80 + col * 80;
      const y = -195 + row * 78;
      const wave = 0.5 + 0.5 * Math.cos(angle * 2 - col * 0.76 - row * 1.02);
      const distribution = 0.5 + 0.5 * Math.sin(angle * 3 - col * 0.5 - row * 0.8);
      const active = clamp(0.42 + activation * 0.38 * wave
                         + regulation * (0.30 + Math.sin(angle * 2) * 0.02)
                         + balanced * (0.23 + 0.10 * distribution));
      const module = ctx.createLinearGradient(x - 29, y - 24, x + 29, y + 24);
      module.addColorStop(0, mix([197, 207, 178], [231, 225, 187], active));
      module.addColorStop(1, mix([169, 190, 168], [205, 211, 175], active));
      box(x - 29, y - 24, 58, 48, 7, module, '#637e7c', 2.8);
      box(x - 9, y - 8, 18, 16, 3,
        mix([155, 168, 142], [233, 216, 162], active), '#738773', 1.4);
      for (const yy of [y - 17, y + 17]) {
        line(x - 10, yy, x + 10, yy, '#9caa87', 1.3);
      }
    }
  }
  // Explicit port masks the intentional trace crossing of the diffuser rim.
  box(-12, 29, 24, 16, 4, '#b0c6b4', '#658b8a', 2);

  // Integrated power regulator. The small arc is inside its component housing.
  for (const y of [96, 118, 140]) {
    for (const side of [-1, 1]) line(side * 55, y, side * 64, y, '#72978f', 2.6);
  }
  box(-55, 82, 110, 73, 10, '#a5bfb2', ink, 3.3);
  for (const x of [-29, 0, 29]) line(x - 5, 94, x + 5, 94, '#7b9e91', 1.7);
  const load = 0.72 * activation + 0.43 * regulation + 0.54 * balanced
              + 0.025 * Math.sin(angle * 2) * (activation + balanced * 0.4);
  ctx.beginPath();
  ctx.arc(0, 130, 25, Math.PI, TAU);
  ctx.strokeStyle = '#6b8c89';
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(0, 130, 25, Math.PI, Math.PI + Math.PI * load);
  ctx.strokeStyle = '#d1bb88';
  ctx.lineWidth = 3.2;
  ctx.stroke();
  const needle = Math.PI + Math.PI * load;
  line(0, 130, Math.cos(needle) * 19, 130 + Math.sin(needle) * 19, ink, 2.5);
  circle(0, 130, 3.4, ink, null, 0);

  // Flat front-elevation screw base and terminal; no extrusion or reflected light.
  box(-43, 327, 86, 35, 11, '#a3b3b5', ink, 4.7);
  const base = ctx.createLinearGradient(-106, 209, 106, 330);
  base.addColorStop(0, '#b8c4cb');
  base.addColorStop(1, '#8da3b2');
  box(-106, 209, 212, 121, 12, base, ink, 5);
  for (let n = 0; n < 4; n++) {
    box(-98, 222 + n * 24, 196, 12, 5,
        n % 2 === 0 ? '#a7b9c0' : '#9bafb9', '#627b8e', 1.8);
  }
  box(-121, 177, 242, 37, 9, '#b0c3c4', ink, 4.6);
  line(-99, 195, 99, 195, '#8da9aa', 1.7);

  ctx.restore();
  ctx.beginPath();
}

/*
 * 07 — CHARGE FORWARD / SUSTAINABLE ELECTRIC MOBILITY
 * Pure Canvas 2D: draw(ctx, timeInSeconds, width, height).
 * 25 seconds; three scenes: connection / energy transfer / steady charging.
 * Fixed connector and cable geometry; exact 25-second visual loop.
 * Static background. No assets, text, blur, shadows, glow, or camera motion.
 * Video export target: 3840 x 2160, 60 fps, 100,000,000 bits per second.
 * The host video exporter must set the bitrate; Canvas only renders pixels.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const phase = loopT / duration;
  const angle = TAU * phase;
  const scale = minSide / 1000;
  const ink = '#193f57';
  const clamp = (v, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, v));
  const smooth = v => {
    const u = clamp(v);
    return u * u * u * (u * (u * 6 - 15) + 10);
  };
  const mix = (a, b, u) => 'rgb(' + [0, 1, 2].map(
    i => Math.round(a[i] + (b[i] - a[i]) * u)
  ).join(',') + ')';
  const transition = smooth((sceneProgress - 0.78) / 0.22);
  const emphasis = [0, 0, 0];
  emphasis[currentScene] = 1 - transition;
  emphasis[(currentScene + 1) % sceneCount] = transition;
  const connection = emphasis[0];
  const transfer = emphasis[1];
  const steady = emphasis[2];

  function rounded(x, y, w, h, r) {
    const q = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + q, y);
    ctx.lineTo(x + w - q, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + q);
    ctx.lineTo(x + w, y + h - q);
    ctx.quadraticCurveTo(x + w, y + h, x + w - q, y + h);
    ctx.lineTo(x + q, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - q);
    ctx.lineTo(x, y + q);
    ctx.quadraticCurveTo(x, y, x + q, y);
    ctx.closePath();
  }

  function box(x, y, w, h, r, fill, stroke, lw) {
    rounded(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  function line(x1, y1, x2, y2, stroke, lw) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw;
    ctx.stroke();
  }

  function circle(x, y, r, fill, stroke, lw) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  function cablePath() {
    ctx.beginPath();
    ctx.moveTo(-430, -55);
    ctx.lineTo(-430, 290);
    ctx.arc(-350, 290, 80, Math.PI, Math.PI / 2, true);
    ctx.lineTo(10, 370);
    ctx.arc(10, 290, 80, Math.PI / 2, 0, true);
    ctx.lineTo(90, 244);
  }

  // Exact arc-length sampling gives every current packet the same linear speed.
  function cablePoint(u) {
    const arcLength = 40 * Math.PI;
    const total = 345 + arcLength + 360 + arcLength + 46;
    let d = u * total;
    if (d <= 345) return [-430, -55 + d];
    if ((d -= 345) <= arcLength) {
      const a = Math.PI - d / 80;
      return [-350 + 80 * Math.cos(a), 290 + 80 * Math.sin(a)];
    }
    if ((d -= arcLength) <= 360) return [-350 + d, 370];
    if ((d -= 360) <= arcLength) {
      const a = Math.PI / 2 - d / 80;
      return [10 + 80 * Math.cos(a), 290 + 80 * Math.sin(a)];
    }
    d -= arcLength;
    return [90, 290 - d];
  }

  function gripPath() {
    ctx.beginPath();
    ctx.moveTo(9, -126);
    ctx.lineTo(171, -126);
    ctx.quadraticCurveTo(192, -126, 190, -104);
    ctx.lineTo(169, 165);
    ctx.quadraticCurveTo(167, 195, 139, 199);
    ctx.lineTo(41, 199);
    ctx.quadraticCurveTo(13, 195, 11, 165);
    ctx.lineTo(-10, -104);
    ctx.quadraticCurveTo(-12, -126, 9, -126);
    ctx.closePath();
  }

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.filter = 'none';
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.miterLimit = 2;

  // Background and registration marks are completely independent of time.
  const background = ctx.createLinearGradient(0, 0, width, height);
  background.addColorStop(0, '#194b74');
  background.addColorStop(0.5, '#366f89');
  background.addColorStop(1, '#79a6aa');
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2);
  ctx.scale(scale, scale);
  for (const side of [-1, 1]) {
    for (const y of [-376, 376]) {
      const sy = y < 0 ? 1 : -1;
      ctx.beginPath();
      ctx.moveTo(side * 622, y + sy * 22);
      ctx.lineTo(side * 622, y);
      ctx.lineTo(side * 600, y);
      ctx.strokeStyle = 'rgba(210,229,218,0.22)';
      ctx.lineWidth = 1.8;
      ctx.stroke();
    }
  }

  // Centers the complete connector-and-cable silhouette, not just the grip.
  ctx.translate(112, 0);
  cablePath();
  ctx.strokeStyle = ink;
  ctx.lineWidth = 22;
  ctx.stroke();
  cablePath();
  const cable = ctx.createLinearGradient(-430, -55, 90, 370);
  cable.addColorStop(0, '#a4c6be');
  cable.addColorStop(1, '#75aaa8');
  ctx.strokeStyle = cable;
  ctx.lineWidth = 14;
  ctx.stroke();
  cablePath();
  ctx.strokeStyle = '#6f9f9f';
  ctx.lineWidth = 2;
  ctx.stroke();
  for (let n = 0; n < 6; n++) {
    const u = (phase * 3 + n / 6) % 1;
    const p = cablePoint(u);
    ctx.globalAlpha = Math.pow(Math.sin(Math.PI * u), 2)
                    * (0.55 + 0.38 * transfer + 0.10 * steady);
    circle(p[0], p[1], 3.4, '#e6c78e', null, 0);
  }
  ctx.globalAlpha = 1;

  box(-454, -128, 48, 76, 11, '#c6d9cd', ink, 4.2);
  for (let n = 0; n < 3; n++) {
    line(-441, -108 + n * 17, -419, -108 + n * 17, '#709b9b', 2.5);
  }

  // Cable boot sits behind the fixed grip and covers its cable attachment.
  box(54, 186, 72, 69, 11, '#8db3ae', ink, 4.7);
  for (const y of [218, 232, 246]) line(64, y, 116, y, '#5d9298', 2.2);
  gripPath();
  const grip = ctx.createLinearGradient(-10, -126, 190, 199);
  grip.addColorStop(0, '#e1e9dd');
  grip.addColorStop(1, '#bdd5c9');
  ctx.fillStyle = grip;
  ctx.fill();
  ctx.strokeStyle = ink;
  ctx.lineWidth = 5.5;
  ctx.stroke();
  box(26, -72, 128, 209, 18, '#8db6b2', '#507d88', 3);

  // Matte inlaid power symbol; its geometry never changes.
  ctx.beginPath();
  ctx.moveTo(91, -42);
  ctx.lineTo(65, -3);
  ctx.lineTo(86, -3);
  ctx.lineTo(77, 31);
  ctx.lineTo(115, -14);
  ctx.lineTo(92, -14);
  ctx.lineTo(104, -42);
  ctx.closePath();
  ctx.fillStyle = '#ddc799';
  ctx.fill();
  ctx.strokeStyle = ink;
  ctx.lineWidth = 3;
  ctx.stroke();

  const level = 0.42 * connection + 0.78 * transfer + 0.66 * steady
              + Math.sin(angle * 2) * (0.035 * connection + 0.025 * transfer + 0.012 * steady);
  for (let n = 0; n < 5; n++) {
    const active = smooth((level - (n + 0.25) / 5) * 5);
    box(43 + n * 20, 85, 13, 24, 3,
      mix([124, 164, 158], [41, 103, 122], active), '#547f85', 1.3);
  }
  for (const y of [154, 165, 176]) line(44, y, 136, y, '#89aba0', 2.2);

  // The front-facing head intentionally overlaps its fixed grip collar.
  const head = ctx.createLinearGradient(-38, -350, 218, -102);
  head.addColorStop(0, '#e4ebdf');
  head.addColorStop(1, '#c0d8ce');
  box(-38, -350, 256, 248, 35, head, ink, 5.5);
  circle(90, -245, 88, '#547f90', ink, 5);
  circle(90, -245, 72, '#2f6077', '#8eb5b6', 2.3);

  const pins = [[65,-278,12],[115,-278,12],
                [48,-244,12],[90,-244,12],[132,-244,12],
                [75,-209,10],[105,-209,10]];
  for (let n = 0; n < pins.length; n++) {
    const [x,y,r] = pins[n];
    const wave = Math.pow(0.5 + 0.5 * Math.cos(angle * 3 - n * 0.62), 2);
    const active = clamp(0.16 + 0.38 * connection * wave + 0.58 * transfer * wave
                       + 0.24 * steady * (0.6 + wave * 0.4));
    circle(x, y, r, '#a9c5bb', ink, 2.2);
    circle(x, y, r * 0.53,
      mix([49, 97, 111], [192, 175, 129], active), ink, 1.1);
  }
  for (const [x,y] of [[11,-245],[169,-245],[90,-324]]) {
    circle(x,y,3.3,'#b8d0c6',ink,1.3);
  }
  box(17, -142, 146, 18, 5, '#9dbeb5', '#618b90', 1.8);
  for (let n = 0; n < 7; n++) {
    line(34 + n * 19, -137, 34 + n * 19, -129, '#567f86', 1.7);
  }

  ctx.restore();
  ctx.beginPath();
}

/*
 * 08 — CARBON CAPTURE / CLEANER INDUSTRIAL SYSTEMS
 * Pure Canvas 2D: draw(ctx, timeInSeconds, width, height).
 * 25 seconds; three scenes: intake / adsorption / clean-air output.
 * Exact 25-second loop; fixed front elevation and static background.
 * No assets, font dependencies, blur, shadows, glow, or camera movement.
 * Video export target: 3840 x 2160, 60 fps, 100,000,000 bits per second.
 * The host video exporter must set the bitrate; Canvas only renders pixels.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const phase = loopT / duration;
  const angle = TAU * phase;
  const scale = minSide / 1000;
  const ink = '#253c4d';
  const clamp = (v, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, v));
  const smooth = v => {
    const u = clamp(v);
    return u * u * u * (u * (u * 6 - 15) + 10);
  };
  const mix = (a, b, u) => 'rgb(' + [0, 1, 2].map(
    i => Math.round(a[i] + (b[i] - a[i]) * u)
  ).join(',') + ')';
  const transition = smooth((sceneProgress - 0.78) / 0.22);
  const emphasis = [0, 0, 0];
  emphasis[currentScene] = 1 - transition;
  emphasis[(currentScene + 1) % sceneCount] = transition;
  const intake = emphasis[0];
  const adsorption = emphasis[1];
  const output = emphasis[2];
  const lanes = [-110, -38, 34, 106];
  const filterCenters = [-176, 0, 176];
  const targets = [0, 1, 2, 0];

  function rounded(x, y, w, h, r) {
    const q = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + q, y);
    ctx.lineTo(x + w - q, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + q);
    ctx.lineTo(x + w, y + h - q);
    ctx.quadraticCurveTo(x + w, y + h, x + w - q, y + h);
    ctx.lineTo(x + q, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - q);
    ctx.lineTo(x, y + q);
    ctx.quadraticCurveTo(x, y, x + q, y);
    ctx.closePath();
  }

  function box(x, y, w, h, r, fill, stroke, lw) {
    rounded(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  function line(x1, y1, x2, y2, stroke, lw) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw;
    ctx.stroke();
  }

  function circle(x, y, r, fill, stroke, lw) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  // Integral of the quintic easing function, used to ease velocity rather than
  // scale the particles. All four lanes share a 160-unit/second cruise speed.
  function velocityIntegral(q) {
    return q * q * q * q * (q * q - 3 * q + 2.5);
  }

  function travel(distance, age) {
    const speed = 160;
    const ramp = 0.45;
    const cruise = distance / speed - ramp;
    const arrival = cruise + 2 * ramp;
    let position;
    if (age <= ramp) {
      position = speed * ramp * velocityIntegral(clamp(age / ramp));
    } else if (age <= ramp + cruise) {
      position = speed * ramp * 0.5 + speed * (age - ramp);
    } else if (age < arrival) {
      const q = clamp((age - ramp - cruise) / ramp);
      position = speed * ramp * 0.5 + speed * cruise
               + speed * ramp * (q - velocityIntegral(q));
    } else position = distance;
    return { position, arrival };
  }

  const events = [];
  for (let row = 0; row < 4; row++) {
    const center = filterCenters[targets[row]];
    const goal = center - 50;
    const age = ((phase * 4 + row * 0.19) % 1) * (duration / 4);
    const motion = travel(goal + 493, age);
    const envelope = smooth(age / 0.22)
                   * (1 - smooth((age - motion.arrival - 0.65) / 0.7));
    const captured = smooth((age - motion.arrival + 0.24) / 0.24)
                   * (1 - smooth((age - motion.arrival - 0.65) / 0.7));
    events.push({ x: -493 + motion.position, y: lanes[row], center, goal,
                  opacity: envelope * (0.52 + 0.40 * intake + 0.28 * adsorption),
                  captured });
