      const u = (phase * 5 + n / 2 + row * 0.12) % 1;
      const x = 351 + u * 142;
      ctx.globalAlpha = Math.pow(Math.sin(Math.PI * u), 2) * (0.50 + output * 0.45);
      line(x - 6, lanes[row], x + 6, lanes[row], '#a8d0bb', 3.8);
    }
  }
  ctx.globalAlpha = 1;

  // Housing occlusion is intentional: airborne rings are hidden while they
  // traverse a cartridge, then reappear in the next open air channel.
  for (const event of events) particle(event);
  for (let col = 0; col < 3; col++) {
    const x = filterCenters[col];
    const response = 0.5 + 0.5 * Math.sin(angle * 2 - col * 0.72);
    const active = 0.16 + adsorption * (0.28 + response * 0.22);
    const filter = ctx.createLinearGradient(x - 39, -158, x + 39, 152);
    filter.addColorStop(0, mix([174, 199, 184], [212, 197, 160], active));
    filter.addColorStop(1, mix([135, 172, 164], [183, 167, 139], active));
    box(x - 39, -158, 78, 310, 11, filter, ink, 3.7);
    for (const y of lanes) {
