/*
 * 05 — WATER LOOP / SMART WATER CONSERVATION
 * Standalone Canvas 2D: draw(ctx, timeInSeconds, width, height).
 * 25 seconds; three scenes: filtration / storage / recirculation.
 * Exact 25-second loop, fixed silhouette, fixed background, no external assets.
 * No blur, shadows, glow, camera movement, or decorative moving particles.
 * Export target: 3840 x 2160, 60 fps, 100,000,000 bits per second.
 * Set the encoding bitrate in the host exporter; Canvas itself renders pixels.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const phase = loopT / duration;
  const angle = TAU * phase;
  const scale = minSide / 1000;
  const ink = '#24495c';
  const clamp = (v, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, v));
  const smooth = v => {
    const u = clamp(v);
    return u * u * u * (u * (u * 6 - 15) + 10);
  };
  const mix = (a, b, u) => 'rgb(' + [0, 1, 2].map(
    i => Math.round(a[i] + (b[i] - a[i]) * u)
  ).join(',') + ')';
  const transition = smooth((sceneProgress - 0.78) / 0.22);
  const emphasis = [0, 0, 0];
  emphasis[currentScene] = 1 - transition;
  emphasis[(currentScene + 1) % sceneCount] = transition;
  const filtration = emphasis[0];
  const storage = emphasis[1];
  const recirculation = emphasis[2];
  const stored = currentScene === 1 ? smooth(sceneProgress)
               : currentScene === 2 ? 1 - smooth(sceneProgress) : 0;

  function rounded(x, y, w, h, r) {
    const q = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + q, y);
    ctx.lineTo(x + w - q, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + q);
    ctx.lineTo(x + w, y + h - q);
    ctx.quadraticCurveTo(x + w, y + h, x + w - q, y + h);
    ctx.lineTo(x + q, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - q);
    ctx.lineTo(x, y + q);
    ctx.quadraticCurveTo(x, y, x + q, y);
    ctx.closePath();
  }

  function box(x, y, w, h, r, fill, stroke, lw) {
    rounded(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  function line(x1, y1, x2, y2, stroke, lw) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw;
    ctx.stroke();
  }

  function circle(x, y, r, fill) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    ctx.fillStyle = fill;
    ctx.fill();
  }

  function droplet() {
    ctx.beginPath();
    ctx.moveTo(0, -396);
    ctx.bezierCurveTo(-44, -325, -268, -126, -294, 42);
    ctx.bezierCurveTo(-328, 254, -177, 387, 0, 388);
    ctx.bezierCurveTo(177, 387, 328, 254, 294, 42);
    ctx.bezierCurveTo(268, -126, 44, -325, 0, -396);
    ctx.closePath();
  }

  // One closed circulation route, parameterized by actual line and arc lengths.
  // Sections: 0 outlet pipe; 1 reservoir; 2 return pipe; 3 filter interior.
  const segments = [];
  function L(x0, y0, x1, y1, section) {
    segments.push({ kind: 0, x0, y0, x1, y1, section,
                    length: Math.hypot(x1 - x0, y1 - y0) });
  }
  function A(cx, cy, r, a0, a1, section) {
    segments.push({ kind: 1, cx, cy, r, a0, a1, section,
                    length: Math.abs(a1 - a0) * r });
  }
  L(-106, 35, -165, 35, 0);
  A(-165, 60, 25, -Math.PI / 2, -Math.PI, 0);
  L(-190, 60, -190, 187, 0);
  A(-165, 187, 25, Math.PI, Math.PI / 2, 0);
  L(-165, 212, -132, 212, 0);
  L(-132, 212, 132, 212, 1);
  L(132, 212, 165, 212, 2);
  A(165, 187, 25, Math.PI / 2, 0, 2);
  L(190, 187, 190, -90, 2);
  A(165, -90, 25, 0, -Math.PI / 2, 2);
  L(165, -115, 106, -115, 2);
  L(106, -115, 20, -115, 3);
  A(20, -95, 20, -Math.PI / 2, -Math.PI, 3);
  L(0, -95, 0, 15, 3);
  A(-20, 15, 20, 0, Math.PI / 2, 3);
  L(-20, 35, -106, 35, 3);
  const routeLength = segments.reduce((sum, s) => sum + s.length, 0);

  function point(s, u) {
    if (s.kind === 0) return [s.x0 + (s.x1 - s.x0) * u, s.y0 + (s.y1 - s.y0) * u];
    const a = s.a0 + (s.a1 - s.a0) * u;
    return [s.cx + s.r * Math.cos(a), s.cy + s.r * Math.sin(a)];
  }

  function trace(section) {
    let first = true;
    ctx.beginPath();
    for (const s of segments) {
      if (s.section !== section) continue;
      if (first) {
        const p = point(s, 0);
        ctx.moveTo(p[0], p[1]);
        first = false;
      }
      if (s.kind === 0) ctx.lineTo(s.x1, s.y1);
      else ctx.arc(s.cx, s.cy, s.r, s.a0, s.a1, s.a1 < s.a0);
    }
  }

  const packets = [];
  for (let n = 0; n < 12; n++) {
    let d = ((phase * 2 + n / 12) % 1) * routeLength;
    let s = segments[segments.length - 1];
    for (const candidate of segments) {
      s = candidate;
      if (d <= s.length) break;
      d -= s.length;
    }
    const p = point(s, clamp(d / s.length));
    packets.push({ x: p[0], y: p[1], section: s.section });
  }

  function drawPackets(section) {
    for (const p of packets) {
      if (p.section === section) circle(p.x, p.y, 2.6, '#e2edda');
    }
  }

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.filter = 'none';
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.miterLimit = 2;

  // Every background value is independent of time.
  const background = ctx.createLinearGradient(0, 0, width, height);
  background.addColorStop(0, '#173f57');
  background.addColorStop(0.5, '#376a7c');
  background.addColorStop(1, '#779fa6');
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2);
  ctx.scale(scale, scale);

  for (const side of [-1, 1]) {
    for (const y of [-382, 382]) {
      const sy = y < 0 ? 1 : -1;
      ctx.beginPath();
      ctx.moveTo(side * 616, y + sy * 22);
      ctx.lineTo(side * 616, y);
      ctx.lineTo(side * 594, y);
      ctx.strokeStyle = 'rgba(202,226,224,0.22)';
      ctx.lineWidth = 1.8;
      ctx.stroke();
    }
  }

  droplet();
  const shell = ctx.createLinearGradient(-250, -300, 270, 388);
  shell.addColorStop(0, '#d6e9e4');
  shell.addColorStop(1, '#a7cfd3');
  ctx.fillStyle = shell;
  ctx.fill();
  ctx.strokeStyle = ink;
  ctx.lineWidth = 6;
  ctx.stroke();
  ctx.save();
  ctx.scale(0.93, 0.93);
  droplet();
  ctx.strokeStyle = '#81afb9';
  ctx.lineWidth = 2.1;
  ctx.stroke();
  ctx.restore();

  for (const section of [0, 2]) {
    trace(section);
    ctx.strokeStyle = ink;
    ctx.lineWidth = 14;
    ctx.stroke();
    trace(section);
    const active = section === 0 ? filtration : recirculation;
    ctx.strokeStyle = mix([117, 163, 174], [70, 132, 152], 0.25 + 0.60 * active);
    ctx.lineWidth = 8;
    ctx.stroke();
    drawPackets(section);
  }

  // Supply stem attaches to the top of the filter housing.
  line(0, -224, 0, -145, ink, 14);
  line(0, -224, 0, -145, '#6f9fab', 8);
  for (let n = 0; n < 3; n++) {
    const u = (phase * 4 + n / 3) % 1;
    ctx.globalAlpha = Math.pow(Math.sin(Math.PI * u), 2) * (0.35 + 0.55 * filtration);
    circle(0, -223 + u * 77, 2.6, '#e2edda');
  }
  ctx.globalAlpha = 1;
  box(-43, -265, 86, 42, 11, '#d6e4d9', ink, 3.8);
  for (const x of [-21, 0, 21]) line(x, -253, x, -236, '#7da5a6', 2.5);

  // Filter: the membrane layers intentionally occlude the fluid guide below.
  const filterBody = ctx.createLinearGradient(-106, -146, 106, 64);
  filterBody.addColorStop(0, '#e0e9df');
  filterBody.addColorStop(1, '#bfd8d4');
  box(-106, -146, 212, 210, 18, filterBody, ink, 4.5);
  trace(3);
  ctx.strokeStyle = '#87afb3';
  ctx.lineWidth = 7;
  ctx.stroke();
  drawPackets(3);
  for (let row = 0; row < 3; row++) {
    const y = -105 + row * 52;
    const response = 0.5 + 0.5 * Math.cos(angle * 3 - row * 1.18);
    const active = 0.18 + filtration * (0.28 + response * 0.35);
    box(-82, y, 164, 22, 5,
      mix([136, 177, 184], [202, 217, 183], active), '#557e89', 2);
    for (let pore = 0; pore < 9; pore++) {
      const x = -64 + pore * 16;
      line(x, y + 7, x, y + 15, '#547985', 2.1);
    }
  }
  box(-115, 24, 18, 22, 4, '#bad3cb', ink, 2.5);
  box(97, -126, 18, 22, 4, '#bad3cb', ink, 2.5);
  box(-12, -153, 24, 14, 4, '#bad3cb', ink, 2.5);

  // Reservoir liquid is clipped to its fixed inset, with a small periodic wave.
  box(-132, 135, 264, 145, 18, '#d5e4df', ink, 4.5);
  ctx.save();
  rounded(-126, 141, 252, 133, 12);
  ctx.clip();
  const waterY = 184 - stored * 21;
  ctx.beginPath();
  for (let j = 0; j <= 48; j++) {
    const u = j / 48;
    const x = -126 + u * 252;
    const y = waterY + 3.6 * Math.sin(TAU * u + angle * 3);
    if (j === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.lineTo(126, 274);
  ctx.lineTo(-126, 274);
  ctx.closePath();
  const water = ctx.createLinearGradient(0, 157, 0, 274);
  water.addColorStop(0, '#7dbac1');
  water.addColorStop(1, '#4e91a6');
  ctx.fillStyle = water;
  ctx.fill();
  trace(1);
  ctx.strokeStyle = '#4b899c';
  ctx.lineWidth = 2;
  ctx.stroke();
  drawPackets(1);
  ctx.restore();
  box(-132, 135, 264, 145, 18, null, ink, 4.5);
  for (const y of [158, 183, 240, 258]) {
    line(-110, y, -96, y, '#4d7e8d', 1.9);
  }
  box(-141, 201, 16, 22, 4, '#b1cfd0', ink, 2.5);
  box(125, 201, 16, 22, 4, '#b1cfd0', ink, 2.5);

  // Integrated six-segment conservation gauge, without text or emissive effects.
  box(-110, 302, 220, 40, 11, '#d9e7dc', ink, 3.7);
  const level = 0.68 + 0.07 * filtration * Math.sin(angle)
                     + 0.10 * storage * Math.sin(angle * 2 - 0.3)
                     + 0.035 * recirculation * Math.sin(angle * 3);
  for (let n = 0; n < 6; n++) {
    const active = smooth((level - (n + 0.25) / 6) * 6);
    box(-90 + n * 31, 312, 25, 20, 3.5,
      mix([157, 190, 188], [54, 123, 140], active), '#779f9f', 1.15);
  }

  ctx.restore();
  ctx.beginPath();
}

